import React, { createContext, useState, useEffect, useContext, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../services/apiService';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [socket, setSocket] = useState(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const navigate = useNavigate();
  // Initialize WebSocket connection
  const initWebSocket = useCallback((token) => {
    if (!token || socket) return null;
    try {
      const wsProtocol = window.location.protocol === 'https:' ? 'wss://' : 'ws://';
      const wsUrl = `${wsProtocol}${window.location.hostname}:${process.env.REACT_APP_WS_PORT || 5000}?token=${token}`;
      
      console.log('Initializing WebSocket connection to:', wsUrl);
      
      const ws = new WebSocket(wsUrl);
      
      ws.onopen = () => {
        console.log('WebSocket connected');
        setSocket(ws);
      };
      ws.onerror = (error) => {
        console.error('WebSocket error:', error);
        toast.error('Connection error. Some features may not work.');
      };
      ws.onclose = () => {
        console.log('WebSocket disconnected');
        setSocket(null);
      };
      return ws;
    } catch (err) {
      console.error('Failed to initialize WebSocket:', err);
      return null;
    }
  }, [socket]);
  // Clean up WebSocket connection
  const cleanupWebSocket = useCallback(() => {
    if (socket) {
      socket.close(1000, 'User logged out');
      setSocket(null);
    }
  }, [socket]);
  // Check authentication status on mount
  useEffect(() => {
    let ws = null;
    let isMounted = true;
    
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) {
          // No token, set as not authenticated
          setUser(null);
          return;
        }
        
        // If we have a token, verify it
        try {
          const response = await api.get('/auth/me', {
            // Don't retry this request to avoid infinite loading
            retry: 0
          });
          
          if (isMounted) {
            setUser(response.data.user);
            // Initialize WebSocket after successful auth
            ws = initWebSocket(token);
          }
        } catch (error) {
          console.error('Token validation failed:', error);
          if (error.response?.status !== 401) {
            // Only show error if it's not a 401 (unauthorized)
            toast.error('Failed to verify session. Please log in again.');
          }
          localStorage.removeItem('token');
          setUser(null);
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        if (isMounted) {
          setUser(null);
          // Don't show error toast here to avoid spamming the user
        }
      } finally {
        if (isMounted) {
          setLoading(false);
          setIsInitialized(true);
        }
      }
    };

    checkAuth();
    
    return () => {
      isMounted = false;
      if (ws) {
        cleanupWebSocket(ws);
      }
    };
  }, [initWebSocket, cleanupWebSocket]);

  // Login function with enhanced error handling and rate limiting support
  const login = async (email, password) => {
    setLoading(true);
    setError(null);
  
    try {
      const response = await api.post('/auth/login', { email, password }, { 
        retry: 3,
        retryCount: 0
      });
      
      const { token, user } = response.data;
      
      // Store token in localStorage
      localStorage.setItem('token', token);
      
      // Set user state first
      setUser(user);
      
      // Initialize WebSocket
      initWebSocket(token);
      
      // Show success message
      toast.success('Successfully logged in!');
      
      // Navigate after state is updated
      setTimeout(() => {
        navigate('/dashboard', { replace: true });
      }, 100);
      
      return { success: true };
    } catch (error) {
      let errorMessage = 'Login failed. Please try again.';
      
      if (error.response?.status === 429) {
        errorMessage = 'Too many login attempts. Please wait a moment and try again.';
      } else if (error.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error.message) {
        errorMessage = error.message;
      }
      
      setError(errorMessage);
      toast.error(errorMessage);
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
    }
  };

  // Register function with validation
  const register = async (userData) => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await api.post('/auth/register', userData);
      const { token, user } = response.data;
      
      localStorage.setItem('token', token);
      setUser(user);
      
      // Initialize WebSocket after successful registration
      initWebSocket(token);
      
      toast.success('Registration successful! Welcome to PulsePoint!');
      navigate('/dashboard'); // Navigate after successful registration
      return { success: true };
    } catch (error) {
      const errorMessage = error.response?.data?.message || 'Registration failed. Please try again.';
      setError(errorMessage);
      toast.error(errorMessage);
      return { 
        success: false, 
        message: errorMessage,
        errors: error.response?.data?.errors
      };
    } finally {
      setLoading(false);
    }
  };

  // Logout function with cleanup
  const logout = useCallback(() => {
    localStorage.removeItem('token');
    setUser(null);
    cleanupWebSocket(socket);
    setSocket(null);
    toast.info('You have been logged out.');
    navigate('/login');
  }, [navigate, socket, cleanupWebSocket]);

  // Update user profile
  const updateProfile = async (userData) => {
    try {
      const response = await api.put('/auth/me', userData);
      setUser(prev => ({
        ...prev,
        ...response.data.user
      }));
      toast.success('Profile updated successfully!');
      return { success: true };
    } catch (error) {
      const errorMessage = error.response?.data?.message || 'Failed to update profile.';
      setError(errorMessage);
      toast.error(errorMessage);
      return { 
        success: false, 
        message: errorMessage,
        errors: error.response?.data?.errors
      };
    }
  };

  // Refresh token function
  const refreshToken = async () => {
    try {
      const response = await api.post('/auth/refresh-token');
      const { token, user: userData } = response.data;
      
      localStorage.setItem('token', token);
      setUser(userData);
      
      return { success: true, token };
    } catch (error) {
      console.error('Failed to refresh token:', error);
      logout();
      return { success: false };
    }
  };

  // Context value
  const value = {
    user,
    loading,
    error,
    socket,
    isInitialized,
    isAuthenticated: !!user,
    login,
    register,
    logout,
    updateProfile,
    refreshToken,
    clearError: () => setError(null)
  };

  return (
    <AuthContext.Provider value={value}>
      {isInitialized ? children : null}
    </AuthContext.Provider>
  );
};

// Custom hook to use auth context
const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export { AuthContext, useAuth };
export default AuthContext;
